CREATE TABLE users (id uuid PRIMARY KEY, email text NOT NULL UNIQUE, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), token_hash text NOT NULL UNIQUE, csrf_token text NOT NULL, expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events (id bigserial PRIMARY KEY, actor_id uuid REFERENCES users(id), action text NOT NULL, target text, outcome text NOT NULL, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE auth_events (id bigserial PRIMARY KEY, user_id uuid REFERENCES users(id), action text NOT NULL, success boolean NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE secrets (id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id), name text NOT NULL, version integer NOT NULL DEFAULT 1, ciphertext text NOT NULL, nonce text NOT NULL, tag text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE machines (id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id), name text NOT NULL, os text NOT NULL CHECK(os IN ('linux','windows','unknown')), hostname text, tags jsonb NOT NULL DEFAULT '[]', revision integer NOT NULL DEFAULT 1, config jsonb NOT NULL DEFAULT '{}', capabilities jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE machine_connections (id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id), machine_id uuid NOT NULL REFERENCES machines(id), kind text NOT NULL, config jsonb NOT NULL DEFAULT '{}', credential_ref uuid REFERENCES secrets(id), revision integer NOT NULL DEFAULT 1, state text NOT NULL DEFAULT 'unverified', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE capability_tests (id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES users(id),machine_id uuid NOT NULL REFERENCES machines(id),capability text NOT NULL,state text NOT NULL,reason text,evidence jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz);
CREATE TABLE agent_enrollments (id uuid PRIMARY KEY,machine_id uuid NOT NULL REFERENCES machines(id),token_hash text UNIQUE NOT NULL,expires_at timestamptz NOT NULL,consumed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE agent_certificates (id uuid PRIMARY KEY,machine_id uuid NOT NULL REFERENCES machines(id),serial text UNIQUE NOT NULL,protocol_version integer NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE execution_identities (id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES users(id),machine_id uuid NOT NULL REFERENCES machines(id),name text NOT NULL,os_identity text NOT NULL,restriction_verified boolean NOT NULL DEFAULT false,config jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE permission_grants (id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES users(id),revision integer NOT NULL DEFAULT 1,tools jsonb NOT NULL DEFAULT '[]',machine_ids jsonb NOT NULL DEFAULT '[]',workspace_ids jsonb NOT NULL DEFAULT '[]',profile_ids jsonb NOT NULL DEFAULT '[]',secret_ids jsonb NOT NULL DEFAULT '[]',expires_at timestamptz,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE provider_runtime_pools (id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES users(id),name text NOT NULL,max_concurrency integer NOT NULL DEFAULT 1 CHECK(max_concurrency>0));
CREATE TABLE providers (id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES users(id),name text NOT NULL,adapter text NOT NULL,endpoint text NOT NULL,revision integer NOT NULL DEFAULT 1,credential_ref uuid REFERENCES secrets(id),runtime_pool_id uuid REFERENCES provider_runtime_pools(id),routing_classification text NOT NULL DEFAULT 'unknown',config jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE models (id uuid PRIMARY KEY,provider_id uuid NOT NULL REFERENCES providers(id),model_id text NOT NULL,metadata jsonb NOT NULL DEFAULT '{}',capabilities jsonb NOT NULL DEFAULT '{}',observed_at timestamptz NOT NULL DEFAULT now(),UNIQUE(provider_id,model_id));
CREATE TABLE model_favorites (owner_id uuid NOT NULL REFERENCES users(id),provider_id uuid NOT NULL REFERENCES providers(id),model_id text NOT NULL,PRIMARY KEY(owner_id,provider_id,model_id));
CREATE TABLE capability_probes (id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES users(id),provider_id uuid NOT NULL REFERENCES providers(id),model_id text NOT NULL,capability text NOT NULL,state text NOT NULL,config_revision integer NOT NULL,evidence jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE model_observations (id bigserial PRIMARY KEY,provider_id uuid NOT NULL REFERENCES providers(id),model_id text NOT NULL,kind text NOT NULL,value jsonb NOT NULL,source text NOT NULL,observed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE agent_profiles (id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES users(id),name text NOT NULL,current_revision integer NOT NULL DEFAULT 1,archived_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE agent_profile_revisions (profile_id uuid NOT NULL REFERENCES agent_profiles(id),revision integer NOT NULL,instructions text NOT NULL,definition jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(profile_id,revision));
CREATE TABLE projects (id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES users(id),name text NOT NULL,description text NOT NULL DEFAULT '',instructions text NOT NULL DEFAULT '',instruction_revision integer NOT NULL DEFAULT 1,state text NOT NULL DEFAULT 'active',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE workspaces (id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES users(id),project_id uuid NOT NULL REFERENCES projects(id),name text NOT NULL,type text NOT NULL CHECK(type IN ('native','container')),machine_id uuid NOT NULL REFERENCES machines(id),approved_root_id text NOT NULL,canonical_root text NOT NULL,runtime_path text NOT NULL,revision integer NOT NULL DEFAULT 1,instruction_revision integer NOT NULL DEFAULT 1,instructions text NOT NULL DEFAULT '',state text NOT NULL DEFAULT 'active' CHECK(state IN ('active','archived','unregistered')),quota_bytes bigint NOT NULL DEFAULT 10737418240,environment_id uuid,environment_generation integer,lock_version bigint NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE project_instruction_revisions (project_id uuid NOT NULL REFERENCES projects(id),revision integer NOT NULL,instructions text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(project_id,revision));
CREATE TABLE environment_generations (id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),machine_id uuid NOT NULL REFERENCES machines(id),generation integer NOT NULL,runtime_id text,image_digest text,state text NOT NULL,mount_path text NOT NULL,config jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(workspace_id,generation));
CREATE TABLE runtime_control (singleton boolean PRIMARY KEY DEFAULT true CHECK(singleton),dispatch_enabled boolean NOT NULL DEFAULT false,dispatch_epoch uuid NOT NULL,restore_mode boolean NOT NULL DEFAULT false);
INSERT INTO runtime_control(singleton,dispatch_epoch) VALUES(true,gen_random_uuid());
CREATE TABLE jobs (id uuid PRIMARY KEY,requester_id uuid NOT NULL REFERENCES users(id),idempotency_key text NOT NULL,request_hash text NOT NULL,context jsonb,workspace_id uuid REFERENCES workspaces(id),kind text NOT NULL,payload jsonb NOT NULL DEFAULT '{}',result jsonb,modifies_workspace boolean NOT NULL DEFAULT false,state text NOT NULL CHECK(state IN ('queued','running','waiting','cancelling','completed','failed','cancelled','interrupted')),reason text,lease_owner text,lease_until timestamptz,fence bigint NOT NULL DEFAULT 0,next_run_at timestamptz NOT NULL DEFAULT now(),cancel_requested boolean NOT NULL DEFAULT false,dispatch_epoch uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),started_at timestamptz,ended_at timestamptz,UNIQUE(requester_id,idempotency_key));
CREATE INDEX jobs_claim_idx ON jobs(state,next_run_at);
CREATE TABLE job_attempts (id uuid PRIMARY KEY,job_id uuid NOT NULL REFERENCES jobs(id),previous_attempt_id uuid REFERENCES job_attempts(id),state text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE job_steps (id uuid PRIMARY KEY,job_id uuid NOT NULL REFERENCES jobs(id),sequence integer NOT NULL,kind text NOT NULL,state text NOT NULL,request jsonb NOT NULL DEFAULT '{}',result jsonb,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(job_id,sequence));
CREATE TABLE operations (id uuid PRIMARY KEY,job_id uuid NOT NULL REFERENCES jobs(id),step_id text NOT NULL,request_hash text NOT NULL,request jsonb NOT NULL,machine_id uuid NOT NULL REFERENCES machines(id),environment_generation integer,fence bigint NOT NULL,replay_class text NOT NULL DEFAULT 'mutating',status text NOT NULL,receipt jsonb,outcome jsonb,log_cursor bigint NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(job_id,step_id));
CREATE TABLE dispatch_outbox (id bigserial PRIMARY KEY,job_id uuid NOT NULL REFERENCES jobs(id),operation_id uuid REFERENCES operations(id),kind text NOT NULL,payload jsonb NOT NULL,available_at timestamptz NOT NULL DEFAULT now(),delivered_at timestamptz,lease_owner text,lease_until timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE host_receipts (operation_id uuid NOT NULL REFERENCES operations(id),host_sequence bigint NOT NULL,receipt jsonb NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(operation_id,host_sequence));
CREATE TABLE job_events (id bigserial PRIMARY KEY,job_id uuid NOT NULL REFERENCES jobs(id),sequence bigint NOT NULL,type text NOT NULL,payload jsonb NOT NULL,operation_id uuid REFERENCES operations(id),host_sequence bigint,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(job_id,sequence),UNIQUE(operation_id,host_sequence));
CREATE INDEX job_events_replay_idx ON job_events(job_id,id);
CREATE TABLE workspace_locks (workspace_id uuid PRIMARY KEY REFERENCES workspaces(id),job_id uuid REFERENCES jobs(id),lock_owner text,operation_id uuid REFERENCES operations(id),state text NOT NULL DEFAULT 'held',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE resource_reservations (id uuid PRIMARY KEY,resource_type text NOT NULL,resource_id text NOT NULL,job_id uuid NOT NULL REFERENCES jobs(id),operation_id uuid REFERENCES operations(id),state text NOT NULL,lease_until timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE conversations (id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES users(id),title text NOT NULL,context jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE messages (id uuid PRIMARY KEY,conversation_id uuid NOT NULL REFERENCES conversations(id),job_id uuid REFERENCES jobs(id),role text NOT NULL,content jsonb NOT NULL,state text NOT NULL,model_id text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE inference_requests (id uuid PRIMARY KEY,job_id uuid NOT NULL REFERENCES jobs(id),provider_id uuid NOT NULL REFERENCES providers(id),model_id text NOT NULL,state text NOT NULL,request jsonb NOT NULL DEFAULT '{}',response jsonb,metrics jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz);
CREATE TABLE artifacts (id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES users(id),workspace_id uuid REFERENCES workspaces(id),job_id uuid REFERENCES jobs(id),operation_id uuid REFERENCES operations(id),relative_path text NOT NULL,sha256 text NOT NULL,size_bytes bigint NOT NULL CHECK(size_bytes>=0),mime_type text NOT NULL,storage_key text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE checkpoints (id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),parent_id uuid REFERENCES checkpoints(id),manifest jsonb NOT NULL,manifest_hash text NOT NULL,consistency text NOT NULL,exclusions jsonb NOT NULL DEFAULT '[]',reason text NOT NULL DEFAULT 'manual',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE file_changes (id uuid PRIMARY KEY,workspace_id uuid NOT NULL REFERENCES workspaces(id),job_id uuid REFERENCES jobs(id),operation_id uuid REFERENCES operations(id),path text NOT NULL,before_hash text,after_hash text,kind text NOT NULL,details jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE log_segments (id uuid PRIMARY KEY,job_id uuid NOT NULL REFERENCES jobs(id),storage_key text NOT NULL,sha256 text NOT NULL,start_offset bigint NOT NULL,end_offset bigint NOT NULL,expires_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE metric_samples (id bigserial PRIMARY KEY,machine_id uuid NOT NULL REFERENCES machines(id),boot_id text NOT NULL,sequence bigint NOT NULL,series text NOT NULL,device_id text NOT NULL DEFAULT '',value double precision,unit text NOT NULL,availability text NOT NULL,reason text,source text NOT NULL,observed_at timestamptz NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),UNIQUE(machine_id,boot_id,sequence,series,device_id),CHECK((availability='available' AND value IS NOT NULL) OR availability<>'available'));
CREATE INDEX metric_samples_history_idx ON metric_samples(machine_id,observed_at);
CREATE TABLE metric_rollups (machine_id uuid NOT NULL REFERENCES machines(id),series text NOT NULL,device_id text NOT NULL DEFAULT '',resolution text NOT NULL,bucket timestamptz NOT NULL,min double precision,max double precision,mean double precision,count integer NOT NULL,PRIMARY KEY(machine_id,series,device_id,resolution,bucket));
CREATE TABLE service_targets (id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES users(id),machine_id uuid NOT NULL REFERENCES machines(id),name text NOT NULL,kind text NOT NULL,config jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE service_observations (id bigserial PRIMARY KEY,target_id uuid NOT NULL REFERENCES service_targets(id),state text NOT NULL,reason text,observed_at timestamptz NOT NULL);
CREATE TABLE saved_actions (id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES users(id),name text NOT NULL,current_revision integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE saved_action_revisions (action_id uuid NOT NULL REFERENCES saved_actions(id),revision integer NOT NULL,definition jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(action_id,revision));
CREATE TABLE action_dispatches (id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES users(id),action_id uuid NOT NULL REFERENCES saved_actions(id),action_revision integer NOT NULL,idempotency_key text NOT NULL,request_hash text NOT NULL,job_id uuid REFERENCES jobs(id),request jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(owner_id,idempotency_key));
CREATE TABLE remote_connections (id uuid PRIMARY KEY,machine_id uuid NOT NULL REFERENCES machines(id),kind text NOT NULL,config jsonb NOT NULL,credential_ref uuid REFERENCES secrets(id),owner_id uuid NOT NULL REFERENCES users(id),version integer NOT NULL DEFAULT 1,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE remote_sessions (id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES users(id),auth_session_id uuid NOT NULL REFERENCES sessions(id),machine_id uuid NOT NULL REFERENCES machines(id),connection_id uuid NOT NULL REFERENCES remote_connections(id),kind text NOT NULL,state text NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz,ticket_hash text,ticket_consumed_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE backup_runs (id uuid PRIMARY KEY,status text NOT NULL,manifest jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE restore_runs (id uuid PRIMARY KEY,status text NOT NULL,manifest jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
